CREATE TABLE IF NOT EXISTS admin_users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, base_path TEXT NOT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS sites (id INTEGER PRIMARY KEY AUTOINCREMENT, server_user_id INTEGER, name TEXT NOT NULL, path TEXT UNIQUE NOT NULL, type TEXT NOT NULL DEFAULT 'unknown', cms_type TEXT NULL, is_active INTEGER NOT NULL DEFAULT 1, last_scan_at TEXT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(server_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS scan_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL, finished_at TEXT NULL, status TEXT NOT NULL DEFAULT 'running', scope_type TEXT NOT NULL DEFAULT 'full', scope_value TEXT NULL, files_scanned INTEGER NOT NULL DEFAULT 0, findings_count INTEGER NOT NULL DEFAULT 0, error_text TEXT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS file_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NULL, path TEXT UNIQUE NOT NULL, relative_path TEXT NULL, owner TEXT NULL, "group" TEXT NULL, permissions TEXT NULL, size INTEGER NOT NULL DEFAULT 0, mtime TEXT NULL, sha256 TEXT NULL, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, last_changed_at TEXT NULL, is_missing INTEGER NOT NULL DEFAULT 0, created_at TEXT, updated_at TEXT, FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS findings (id INTEGER PRIMARY KEY AUTOINCREMENT, scan_run_id INTEGER NULL, site_id INTEGER NULL, path TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', type TEXT NOT NULL DEFAULT 'unknown', title TEXT NOT NULL, description TEXT NULL, matched_rules TEXT NULL, sha256 TEXT NULL, size INTEGER NULL, mtime TEXT NULL, owner TEXT NULL, permissions TEXT NULL, first_seen_at TEXT NULL, last_seen_at TEXT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(scan_run_id) REFERENCES scan_runs(id) ON DELETE SET NULL, FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS findings_path_status_idx ON findings(path, status);
CREATE TABLE IF NOT EXISTS log_events (id INTEGER PRIMARY KEY AUTOINCREMENT, site_id INTEGER NULL, log_path TEXT NOT NULL, line_number INTEGER NULL, ip TEXT NULL, method TEXT NULL, uri TEXT NULL, status_code INTEGER NULL, user_agent TEXT NULL, referer TEXT NULL, event_type TEXT NOT NULL, risk TEXT NOT NULL, raw_line TEXT NOT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS quarantine_items (id INTEGER PRIMARY KEY AUTOINCREMENT, finding_id INTEGER NULL, original_path TEXT NOT NULL, quarantine_path TEXT NOT NULL, sha256 TEXT NULL, owner TEXT NULL, "group" TEXT NULL, permissions TEXT NULL, mtime TEXT NULL, reason TEXT NULL, status TEXT NOT NULL DEFAULT 'quarantined', created_at TEXT, updated_at TEXT, FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS rules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT NULL, risk TEXT NOT NULL, type TEXT NOT NULL, pattern TEXT NOT NULL, pattern_type TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS allowlist_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, path_pattern TEXT NULL, sha256 TEXT NULL, reason TEXT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT UNIQUE NOT NULL, value TEXT NULL, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS ai_analyses (id INTEGER PRIMARY KEY AUTOINCREMENT, finding_id INTEGER NOT NULL, provider TEXT NULL, model TEXT NULL, risk TEXT NULL, confidence REAL NULL, summary TEXT NULL, raw_response TEXT NULL, created_at TEXT, updated_at TEXT, FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE CASCADE);
